    """
    Systematically checks sequences starting with (x1, x2) up to length 5 (n=5).
    Returns the maximum length found.
    """

    # --- Step 1: Calculate x3 ---
    if (x2**2 + 1) % (x1 + 1) != 0:
        return 0 # Not an integer x3

    k3 = (x2**2 + 1) // (x1 + 1)
    if k3 < 2:
        return 0 # x3 is not positive

    x3 = k3 - 1

    # Check positivity (already handled by k3 >= 2 and x1 >= 1)
    if x3 <= 0:
        return 0

    # --- Step 2: Calculate x4 ---
    if (x3**2 + 1) % (x2 + 1) != 0:
        return 3 # Sequence terminates at n=3

    k4 = (x3**2 + 1) // (x2 + 1)
    if k4 < 2:
        return 3 # x4 is not positive

    x4 = k4 - 1

    if x4 <= 0:
        return 3

    # --- Step 3: Calculate x5 ---
    if (x4**2 + 1) % (x3 + 1) != 0:
        return 4 # Sequence terminates at n=4

    k5 = (x4**2 + 1) // (x3 + 1)
    if k5 < 2:
        return 4 # x5 is not positive

    x5 = k5 - 1

    if x5 <= 0:
        return 4

    # Sequence reached n=5
    return 5

